// @ts-nocheck
/* eslint-disable */
/**
 * Quick chat engine. GENERATED by tools/sync-quick-chat.mjs from web/WEB-INF/pages/quickchat.xhtml — do not edit; change the script and run `npm run quick-chat:sync`.
 *
 * The script of the Java include, same behaviour line by line: the floating chat box (draggable, resizable, size / position /
 * open state remembered per tab in sessionStorage), the chat page in it, the green dot on the "แชท" button, the
 * window.cbQuickChat* hooks the other pages call, the open-room and "switch to this customer's room" messages.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-quick-chat.mjs):
 *   - the environment is injected (QuickChatEnv): the URL of the chat page in embed mode, "is this the full chat page",
 *     "go to the full chat page" — in Java these were EL (contextPath), location.pathname and location.href;
 *   - the chat page is loaded with iframe.src (the SPA route /chat-embed) instead of fetch + srcdoc; that route restores the
 *     open room from sessionStorage itself (Java injected it into the srcdoc);
 *   - global listeners are removed by the function returned from startQuickChat(); pageChanged() hides the box on the full chat
 *     page and brings it back on the next page: Java did that by reloading the page, the SPA changes page without one.
 */

export interface QuickChatEnv {
  /** URL of the chat page in embed mode (the SPA route /chat-embed, with the base href) */
  embedUrl: string;
  /** true on the full chat page (/chat): the button does not open the box there */
  onChatPage: () => boolean;
  /** the full chat page */
  goFull: () => void;
}

export interface QuickChatHandle {
  /** the "แชท" button: true = handled (box opened / closed) ; false = the button goes to the full chat page */
  toggle: () => boolean;
  /** the route changed: hide the box on the full chat page, bring it back (when it was left open) elsewhere */
  pageChanged: () => void;
  destroy: () => void;
}

export function startQuickChat(env: QuickChatEnv): QuickChatHandle {
            var disposers = [];
            function listen(target, type, fn, opts) {
                target.addEventListener(type, fn, opts);
                disposers.push(function () { target.removeEventListener(type, fn, opts); });
            }
            /* อยู่ใน iframe แชทย่อเอง (หน้าที่ถูกฝัง) → ไม่ต้องมี overlay ซ้อน */
            if (window.top !== window.self) { return { toggle: function () { return false; }, pageChanged: function () {}, destroy: function () {} }; }

            var wrap = document.getElementById('qcWrap');
            var frame = document.getElementById('qcFrame');
            var loadEl = document.getElementById('qcLoad');
            var state = 0;                                   /* 0 ยังไม่โหลด · 1 กำลังโหลด · 2 โหลดแล้ว */

            function onChatPage() { return !!env.onChatPage(); }
            function goFull() { env.goFull(); }

            /* ★ 10/11/2026 — ปุ่ม "แชท" ในแถบซ้ายบอกแค่ว่าแชทย่อเปิดอยู่ด้วยจุดเขียวเล็ก (class qc-open)
               เดิมใช้ class chat-active ซึ่งเป็นสไตล์ "เมนูที่กำลังเปิดอยู่" → เปลี่ยนหน้าไปเมนูอื่นแล้วแชทย่อเปิดกลับ
               ปุ่มแชทแย่งไฮไลต์จากเมนูของหน้าจริง (ดูเหมือนเมนูเปลี่ยนไปเป็นแชท) ; chat-active ให้ groupedMenu ใช้กับหน้าแชทเต็มอย่างเดียว */
            function mark(on) {
                var btn = document.getElementById('chatMenuBtn');
                if (btn) { btn.classList.toggle('qc-open', !!on); }
            }

            function load() {
                if (state !== 0) { return; }
                state = 1;
                loadEl.classList.remove('hide');
                frame.addEventListener('load', function () { loadEl.classList.add('hide'); }, {once: true});
                frame.src = env.embedUrl;
                state = 2;
            }

            /* ★ 10/11/2026 — จำสถานะข้ามหน้าด้วย sessionStorage (ต่อแท็บ): เปิดค้างไว้ + ตำแหน่งที่ลากไป
               เปลี่ยนหน้า = เปิดกล่องกลับมาที่เดิมอัตโนมัติ จนกว่าจะกดปิด (หรือกดขยายไปหน้าแชทเต็ม) ; storage ใช้ไม่ได้ก็ทำงานได้ตามปกติ */
            var K_OPEN = 'qc_open', K_POS = 'qc_pos', K_W = 'qc_w', K_H = 'qc_h', K_ROOM = 'qc_room', K_PP = 'qc_pp';
            function ssGet(k) { try { return window.sessionStorage.getItem(k); } catch (e) { return null; } }
            function ssSet(k, v) { try { if (v === null) { window.sessionStorage.removeItem(k); } else { window.sessionStorage.setItem(k, v); } } catch (e) {} }

            function isMobile() { return window.innerWidth <= 520; }
            /* ใส่ตำแหน่ง (left/top) โดยไม่ให้หลุดขอบจอ ; mobile = เต็มจอ ไม่ใช้ตำแหน่งที่ลาก */
            function place(x, y) {
                if (isMobile()) {
                    wrap.style.left = wrap.style.top = wrap.style.bottom = '';
                    return;
                }
                var w = wrap.offsetWidth, h = wrap.offsetHeight;
                x = Math.max(0, Math.min(x, window.innerWidth - w));
                y = Math.max(0, Math.min(y, window.innerHeight - h));
                wrap.style.left = x + 'px';
                wrap.style.top = y + 'px';
                wrap.style.bottom = 'auto';
            }
            /* ── ความกว้าง: ลากขอบขวา ปรับได้ระหว่าง MIN_W ถึง MAX_W (ไม่เกินจอ) แล้วจำค่าไว้ ── */
            var MIN_W = 320, MAX_W = 760, DEF_W = 400;
            function clampW(w) { return Math.max(MIN_W, Math.min(w, MAX_W, window.innerWidth - 16)); }
            function applyW(w) {
                if (isMobile()) { wrap.style.width = ''; return; }
                wrap.style.width = clampW(w) + 'px';
            }
            function restoreW() {
                var w = parseInt(ssGet(K_W), 10);
                applyW(isNaN(w) ? DEF_W : w);
            }
            var rz = document.getElementById('qcResize'), rzDrag = null;
            rz.addEventListener('pointerdown', function (e) {
                if (isMobile() || e.button !== 0) { return; }
                rzDrag = {x: e.clientX, w: wrap.offsetWidth};
                frame.style.pointerEvents = 'none';
                try { rz.setPointerCapture(e.pointerId); } catch (err) {}
                e.preventDefault();
            });
            rz.addEventListener('pointermove', function (e) {
                if (!rzDrag) { return; }
                applyW(rzDrag.w + (e.clientX - rzDrag.x));
                var r = wrap.getBoundingClientRect();
                if (wrap.style.top) { place(r.left, r.top); }      /* ขยายแล้วชนขอบขวา → ดันกล่องกลับเข้าจอ */
            });
            function endRz() {
                if (!rzDrag) { return; }
                rzDrag = null;
                frame.style.pointerEvents = '';
                ssSet(K_W, String(wrap.offsetWidth));
            }
            rz.addEventListener('pointerup', endRz);
            rz.addEventListener('pointercancel', endRz);
            rz.addEventListener('dblclick', function () { applyW(DEF_W); ssSet(K_W, String(DEF_W)); });

            /* ── ความสูง: ลากขอบบน/ล่าง ปรับได้ MIN_H ถึงเต็มจอ แล้วจำค่าไว้ ── */
            var MIN_H = 360;
            function maxH() { return window.innerHeight - 16; }
            function applyH(h) {
                if (isMobile()) { wrap.style.height = ''; return; }
                if (!h) { wrap.style.height = ''; return; }        /* ไม่เคยปรับ = ใช้ความสูงเริ่มต้นจาก CSS */
                wrap.style.height = Math.max(MIN_H, Math.min(h, maxH())) + 'px';
            }
            function restoreH() {
                var h = parseInt(ssGet(K_H), 10);
                applyH(isNaN(h) ? 0 : h);
            }
            var hzDrag = null;
            function hzBind(el, dir) {
                el.addEventListener('pointerdown', function (e) {
                    if (isMobile() || e.button !== 0) { return; }
                    var r = wrap.getBoundingClientRect();
                    hzDrag = {dir: dir, y: e.clientY, h: r.height, top: r.top, bottom: r.bottom, el: el};
                    wrap.style.top = r.top + 'px';                /* เปลี่ยนมาจัดตำแหน่งด้วย top แล้วสั่งความสูงตรง ๆ */
                    wrap.style.bottom = 'auto';
                    frame.style.pointerEvents = 'none';
                    try { el.setPointerCapture(e.pointerId); } catch (err) {}
                    e.preventDefault();
                });
                el.addEventListener('pointermove', function (e) {
                    if (!hzDrag || hzDrag.el !== el) { return; }
                    var dy = e.clientY - hzDrag.y, h, top = hzDrag.top;
                    if (dir === 'b') {
                        h = Math.min(hzDrag.h + dy, window.innerHeight - hzDrag.top - 4);        /* ล่างไม่เลยขอบจอ */
                    } else {
                        h = Math.min(hzDrag.h - dy, hzDrag.bottom - 4);                          /* บนไม่เลยขอบจอ */
                        top = hzDrag.bottom - Math.max(MIN_H, Math.min(h, maxH()));
                    }
                    h = Math.max(MIN_H, Math.min(h, maxH()));
                    wrap.style.height = h + 'px';
                    wrap.style.top = Math.max(0, top) + 'px';
                });
                function end() {
                    if (!hzDrag || hzDrag.el !== el) { return; }
                    hzDrag = null;
                    frame.style.pointerEvents = '';
                    var r = wrap.getBoundingClientRect();
                    ssSet(K_H, String(Math.round(r.height)));
                    ssSet(K_POS, JSON.stringify({x: Math.round(r.left), y: Math.round(r.top)}));
                }
                el.addEventListener('pointerup', end);
                el.addEventListener('pointercancel', end);
                el.addEventListener('dblclick', function () {
                    wrap.style.height = '';
                    ssSet(K_H, null);
                    var r = wrap.getBoundingClientRect();
                    place(r.left, r.top);
                    r = wrap.getBoundingClientRect();
                    ssSet(K_POS, JSON.stringify({x: Math.round(r.left), y: Math.round(r.top)}));
                });
            }
            hzBind(document.getElementById('qcResizeT'), 't');
            hzBind(document.getElementById('qcResizeB'), 'b');

            function restorePos() {
                var raw = ssGet(K_POS), p = null;
                try { p = raw ? JSON.parse(raw) : null; } catch (e) { p = null; }
                if (p && typeof p.x === 'number' && typeof p.y === 'number') { place(p.x, p.y); }
            }

            function open() {
                /* หน้าลูกค้า (ดู/แก้ไข) ประกาศ window.CB_QC_PROSPECT ไว้ → โหลดแชทย่อครั้งแรกของหน้านี้ ให้เปิดที่ห้องของลูกค้ารายนั้น */
                /* qc_pp = คำสั่ง "สลับไปห้องของลูกค้า X" ที่สั่งไว้ตอนคลิกแล้วหน้าเปลี่ยนก่อนทำเสร็จ (เช่นคลิกแถวในหน้าหลัก) — มาก่อนค่าของหน้า */
                if (state === 0) {
                    var pp = ssGet(K_PP);
                    if (pp) { pendingProspect = pp; } else if (window.CB_QC_PROSPECT) { pendingProspect = window.CB_QC_PROSPECT; }
                }
                wrap.style.display = 'flex';
                restoreW();
                restoreH();
                restorePos();
                mark(true);
                ssSet(K_OPEN, '1');
                load();
            }
            function close() {
                wrap.style.display = 'none';
                mark(false);
                ssSet(K_OPEN, null);
            }

            /* ── ลากย้าย: จับที่หัวกล่อง (ยกเว้นปุ่ม) ── */
            var drag = null;
            var hd = wrap.querySelector('.qc-hd');
            hd.addEventListener('pointerdown', function (e) {
                if (isMobile() || e.button !== 0 || (e.target.closest && e.target.closest('button'))) { return; }
                var r = wrap.getBoundingClientRect();
                drag = {dx: e.clientX - r.left, dy: e.clientY - r.top};
                frame.style.pointerEvents = 'none';      /* iframe กลืนเมาส์ → ปิดชั่วคราวระหว่างลาก */
                try { hd.setPointerCapture(e.pointerId); } catch (err) {}
                e.preventDefault();
            });
            hd.addEventListener('pointermove', function (e) {
                if (drag) { place(e.clientX - drag.dx, e.clientY - drag.dy); }
            });
            function endDrag() {
                if (!drag) { return; }
                drag = null;
                frame.style.pointerEvents = '';
                var r = wrap.getBoundingClientRect();
                ssSet(K_POS, JSON.stringify({x: Math.round(r.left), y: Math.round(r.top)}));
            }
            hd.addEventListener('pointerup', endDrag);
            hd.addEventListener('pointercancel', endDrag);
            /* ย่อ/ขยายหน้าต่างเบราว์เซอร์ → ดึงกล่องกลับเข้าจอ */
            listen(window, 'resize', function () {
                if (wrap.style.display === 'none' || wrap.style.display === '') { return; }
                applyW(parseInt(ssGet(K_W), 10) || DEF_W);
                restoreH();
                var r = wrap.getBoundingClientRect();
                if (wrap.style.top) { place(r.left, r.top); } else if (isMobile()) { place(0, 0); }
            });

            /* หน้าแชทในกรอบแจ้งว่าเปิดห้องไหนอยู่ / กลับไปหน้ารายชื่อ → จำไว้ ใช้ตอนเปลี่ยนหน้า */
            listen(window, 'message', function (e) {
                var d = e.data;
                if (e.source !== frame.contentWindow || !d || d.qcRoom !== 1) { return; }
                ssSet(K_ROOM, JSON.stringify({room: d.room, open: !!d.open}));
                ssSet(K_PP, null);                 /* แชทเลือกห้องแล้ว (ไม่ว่าจากคำสั่งหรือผู้ใช้คลิกเอง) = คำสั่งที่ค้างหมดอายุ */
            });

            /* ★ 10/11/2026 — คลิกลูกค้าในหน้า contracts → ถ้าแชทย่อเปิดอยู่ ให้สลับไปห้องของลูกค้าคนนั้น (LINE ก่อน)
               คืน true = ส่งคำสั่งแล้ว ; แชทย่อไม่ได้เปิด = false ไม่ทำอะไร ; กรอบยังโหลดไม่เสร็จ = เก็บคำสั่งล่าสุดไว้ส่งตอนโหลดเสร็จ */
            var pendingProspect = null;
            function sendProspect(pid) {
                try { frame.contentWindow.postMessage({qcProspect: 1, prospectId: pid}, window.location.origin); } catch (e) {}
            }
            frame.addEventListener('load', function () {
                if (pendingProspect !== null && state === 2) { var p = pendingProspect; pendingProspect = null; sendProspect(p); ssSet(K_PP, null); }
            });
            window.cbQuickChatOpenProspect = function (pid) {
                if (!pid || wrap.style.display === 'none' || wrap.style.display === '') { return false; }
                setTimeout(function () { ssSet(K_PP, null); }, 4000);   /* ไม่มีห้อง = ไม่มีแจ้งกลับ → กันคำสั่งค้างข้ามหน้าไปเรื่อย ๆ */
                ssSet(K_PP, String(pid));          /* จำไว้ก่อน — ถ้าหน้าเปลี่ยนก่อนหน้าแชทตอบกลับ หน้าถัดไปทำต่อให้ (เคลียร์เมื่อแชทแจ้งว่าสลับห้องแล้ว) */
                if (state === 2 && frame.contentDocument && frame.contentDocument.readyState === 'complete') { sendProspect(pid); } else { pendingProspect = pid; }
                return true;
            };

            /* เรียกจากปุ่ม "แชท" — คืน true = จัดการแล้ว (เปิด/ปิด overlay) ; false = ให้ปุ่มไปหน้าแชทเต็มตามเดิม */
            window.cbQuickChat = function () {
                if (onChatPage()) { return false; }
                if (wrap.style.display === 'none' || wrap.style.display === '') { open(); } else { close(); }
                return true;
            };
            /* ใช้เป็น onclick ของปุ่ม: เปิด overlay ถ้าทำได้ ไม่งั้นไปหน้าเต็ม */
            window.cbQuickChatGo = function (url) {
                if (!window.cbQuickChat()) { goFull(); }
            };

            document.getElementById('qcClose').addEventListener('click', close);
            /* ขยาย = ไปหน้าแชทเต็ม → เลิกจำว่าเปิดค้าง (กลับไปหน้าอื่นจะไม่เด้ง overlay ซ้อนกับหน้าแชทที่เพิ่งดู) */
            document.getElementById('qcExpand').addEventListener('click', function () { ssSet(K_OPEN, null); goFull(); });

            /* เปลี่ยนหน้ามาแล้วเจอธงเปิดค้าง → เปิดกลับ (ยกเว้นหน้าแชทเต็ม ซึ่งมีแชทอยู่แล้ว) */
            if (ssGet(K_OPEN) === '1' && !onChatPage()) { open(); }

            function pageChanged() {
                var shown = wrap.style.display === 'flex';
                if (onChatPage()) {
                    if (shown) { wrap.style.display = 'none'; mark(false); }
                } else if (ssGet(K_OPEN) === '1' && !shown) {
                    open();
                }
            }

            return {
                toggle: function () { return window.cbQuickChat(); },
                pageChanged: pageChanged,
                destroy: function destroy() {
                    disposers.splice(0).forEach(function (d) { d(); });
                    mark(false);
                    delete window.cbQuickChat;
                    delete window.cbQuickChatGo;
                    delete window.cbQuickChatOpenProspect;
                }
            };
}
